import{d as g,C as e,o as m,c as h,a3 as i,E as t,j as a,a as u}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"论语·阳货","description":"《论语》第 17 篇「阳货」——二十六章原文与导读。性相近习相远、割鸡焉用牛刀、六言六蔽、兴观群怨、乡愿德之贼、天何言哉、三年之丧。","frontmatter":{"title":"论语·阳货","description":"《论语》第 17 篇「阳货」——二十六章原文与导读。性相近习相远、割鸡焉用牛刀、六言六蔽、兴观群怨、乡愿德之贼、天何言哉、三年之丧。","category":"guide","aliases":["阳货","阳货篇","阳货第十七","论语阳货","lunyu 阳货"],"source":["《论语》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/lunyu/chapter-17.md","filePath":"lizhimingde/sishu-wujing/lunyu/chapter-17.md","lastUpdated":1790316338000}'),p={name:"lizhimingde/sishu-wujing/lunyu/chapter-17.md"},w=g({...p,setup(y){const s=[{id:"yi",label:"一、阳货欲见孔子",showLabel:!0,sentences:[["阳货欲见孔子，孔子不见，",{text:"归",glossary:"kui"},"孔子",{text:"豚",glossary:"tun"},"。孔子时其亡也而往拜之，遇诸涂。谓孔子曰：“来，予与尔言。”曰：“怀其宝而迷其邦，可谓仁乎？”曰：“不可。”“好从事而",{text:"亟",glossary:"qi-ji"},"失时，可谓知乎？”曰：“不可！”“日月逝矣，岁不我与！”孔子曰：“诺，吾将仕矣。”"]],note:"阳货欲见孔子，孔子不见；阳货馈孔子豚。孔子趁其外出而往拜之，遇于途。阳货谓孔子曰：「来，予与尔言」。曰：「怀其宝而迷其邦，可谓仁乎」——怀藏本领而听任国家迷乱，可谓仁乎？曰「不可」。「好从事而亟失时，可谓知乎」——好做事却屡失时机，可谓知乎？曰「不可」。「日月逝矣，岁不我与」——日月流逝，岁不待人。孔子曰：「诺，吾将仕矣」——好，我将出仕。"},{id:"er",label:"二、性相近也，习相远也",showLabel:!0,sentences:[["子曰：“性相近也，习相远也。”"]],note:"「性相近也，习相远也」——人的本性相近，因习染而相远。此为孔子论人性最直接的一句。"},{id:"san",label:"三、唯上知与下愚不移",showLabel:!0,sentences:[["子曰：“唯上知与下愚不移。”"]],note:"「唯上知与下愚不移」——唯有上等的智者与下等的愚者，不可移易。"},{id:"si",label:"四、割鸡焉用牛刀",showLabel:!0,sentences:[["子之武城，闻",{text:"弦歌",glossary:"xiange"},"之声。夫子",{text:"莞尔",glossary:"waner"},"而笑，曰：“割鸡焉用牛刀？”子游对曰：“昔者偃也闻诸夫子曰：‘君子学道则爱人，小人学道则易使也。’”子曰：“二三子，偃之言是也！前言戏之耳。”"]],note:"孔子至武城，闻弦歌之声，莞尔而笑曰：「割鸡焉用牛刀」——杀鸡何必用牛刀？子游（时为武城宰）对曰：「昔者偃也闻诸夫子曰：君子学道则爱人，小人学道则易使也」——昔闻夫子曰：君子学道则爱人，小人学道则易使。孔子曰：「二三子，偃之言是也！前言戏之耳」——学生们，言偃之言是也；前言戏之耳。"},{id:"wu",label:"五、公山弗扰以费畔",showLabel:!0,sentences:[["公山弗扰以费",{text:"畔",glossary:"pan-pan"},"，召，子欲往。子路不说，曰：“末之也已，何必公山氏之之也？”子曰：“夫召我者而岂徒哉？如有用我者，吾其为东周乎！”"]],note:"公山弗扰以费叛，召孔子，孔子欲往。子路不说，曰：「末之也已，何必公山氏之之也」——无处可去便罢了，何必去公山氏那里？孔子曰：「夫召我者而岂徒哉？如有用我者，吾其为东周乎」——召我者岂会无所为？若有人用我，我其将在东方复兴周道乎！"},{id:"liu",label:"六、恭、宽、信、敏、惠",showLabel:!0,sentences:[["子张问仁于孔子，孔子曰：“能行五者于天下为仁矣。”请问之，曰：“恭、宽、信、敏、惠。恭则不",{text:"侮",glossary:"wu-wu"},"，宽则得众，信则人任焉，敏则有功，惠则足以使人。”"]],note:"子张问仁于孔子。孔子曰：「能行五者于天下为仁矣」——能行五者于天下，便为仁。请问之，曰：「恭、宽、信、敏、惠。恭则不侮，宽则得众，信则人任焉，敏则有功，惠则足以使人」——恭则不为人所侮，宽则得众，信则为人所任，敏则有功，惠则足以使人。"},{id:"qi",label:"七、磨而不磷，涅而不缁",showLabel:!0,sentences:[["佛肸召，子欲往。子路曰：“昔者由也闻诸夫子曰：‘亲于其身为不善者，君子不入也。’佛肸以中牟畔，子之往也，如之何？”子曰：“然，有是言也。不曰坚乎，磨而不",{text:"磷",glossary:"lin-lin"},"；不曰白乎，",{text:"涅而不缁",glossary:"nieerbuzi"},"。吾岂",{text:"匏瓜",glossary:"paogua"},"也哉？焉能系而不食？”"]],note:"佛肸召孔子，孔子欲往。子路曰：「昔者由也闻诸夫子曰：亲于其身为不善者，君子不入也。佛肸以中牟畔，子之往也，如之何」——昔闻夫子曰：亲身行不善者之处，君子不入；佛肸据中牟叛，您去，如何？孔子曰：「然，有是言也。不曰坚乎，磨而不磷；不曰白乎，涅而不缁」——是有此言；不是说坚者磨而不薄，白者染而不黑吗（磷＝薄，涅＝染，缁＝黑）？「吾岂匏瓜也哉？焉能系而不食」——我难道是匏瓜吗？怎能悬着而不食？"},{id:"ba",label:"八、六言六蔽",showLabel:!0,sentences:[["子曰：“由也，女闻六言六",{text:"蔽",glossary:"bi-bi2"},"矣乎？”对曰：“未也。”“居！吾语女。好仁不好学，其蔽也愚；好知不好学，其蔽也荡；好信不好学，其蔽也",{text:"贼",glossary:"zei"},"；好直不好学，其蔽也绞；好勇不好学，其蔽也乱；好刚不好学，其蔽也狂。”"]],note:"孔子曰：「由也，女（汝）闻六言六蔽矣乎」——仲由，你闻六言六蔽乎？对曰「未也」。「居！吾语女」：好仁不好学，其蔽也愚；好知不好学，其蔽也荡；好信不好学，其蔽也贼；好直不好学，其蔽也绞；好勇不好学，其蔽也乱；好刚不好学，其蔽也狂。六德若无学以明其理，皆成其蔽。"},{id:"jiu",label:"九、诗可以兴、观、群、怨",showLabel:!0,sentences:[["子曰：“小子何莫学夫《诗》？《诗》可以兴，可以观，可以群，可以怨。",{text:"迩",glossary:"er"},"之事父，远之事君，多识于鸟兽草木之名。”"]],note:"「小子何莫学夫《诗》？《诗》可以兴，可以观，可以群，可以怨。迩之事父，远之事君，多识于鸟兽草木之名」——小子何不学《诗》？《诗》可感发（兴）、可观世（观）、可合群（群）、可讽怨（怨）；近可事父，远可事君，且多识鸟兽草木之名。此为孔子论《诗》之用的名段。"},{id:"shi",label:"十、人而不为《周南》《召南》",showLabel:!0,sentences:[["子谓伯鱼曰：“女为《周南》、《召南》矣乎？人而不为《周南》、《召南》，其犹",{text:"正墙面而立",glossary:"zhengqiangmianerli"},"也与！”"]],note:"子谓伯鱼曰：「女（汝）为《周南》、《召南》矣乎？人而不为《周南》、《召南》，其犹正墙面而立也与」——你学《周南》《召南》了吗？人若不学，就如面墙而立（一无所见）。"},{id:"shiyi",label:"十一、礼云礼云，玉帛云乎哉",showLabel:!0,sentences:[["子曰：“礼云礼云，玉帛云乎哉？乐云乐云，钟鼓云乎哉？”"]],note:"「礼云礼云，玉帛云乎哉？乐云乐云，钟鼓云乎哉」——礼呀礼呀，岂是说的玉帛？乐呀乐呀，岂是说的钟鼓？言礼乐之本不在器物。"},{id:"shier",label:"十二、色厉而内荏",showLabel:!0,sentences:[["子曰：“色厉而内",{text:"荏",glossary:"ren"},"，譬诸小人，其犹",{text:"穿窬",glossary:"chuanyu"},"之盗也与？”"]],note:"「色厉而内荏，譬诸小人，其犹穿窬之盗也与」——外严而内怯，以小人作比，其犹如穿墙之盗乎？"},{id:"shisan",label:"十三、乡愿，德之贼也",showLabel:!0,sentences:[["子曰：“",{text:"乡愿",glossary:"xiangyuan"},"，德之贼也。”"]],note:"「乡愿，德之贼也」——乡愿（貌似忠厚而无是非者），德之贼也。"},{id:"shisi",label:"十四、道听而涂说",showLabel:!0,sentences:[["子曰：“道听而涂说，德之弃也。”"]],note:"「道听而涂说，德之弃也」——道听途说，是德之弃。"},{id:"shiwu",label:"十五、患得患失",showLabel:!0,sentences:[["子曰：“",{text:"鄙夫",glossary:"bifu"},"可与事君也与哉？其未得之也，患得之；既得之，患失之。苟患失之，无所不至矣。”"]],note:"「鄙夫可与事君也与哉？其未得之也，患得之；既得之，患失之。苟患失之，无所不至矣」——鄙夫岂可与事君？其未得则患得，既得则患失；苟患失，则无所不至矣。"},{id:"shiliu",label:"十六、古者民有三疾",showLabel:!0,sentences:[["子曰：“古者民有三疾，今也或是之亡也。古之狂也",{text:"肆",glossary:"si"},"，今之狂也荡；古之",{text:"矜",glossary:"jin-jin"},"也廉，今之矜也",{text:"忿戾",glossary:"fenli"},"；古之愚也直，今之愚也诈而已矣。”"]],note:"「古者民有三疾，今也或是之亡也。古之狂也肆，今之狂也荡；古之矜也廉，今之矜也忿戾；古之愚也直，今之愚也诈而已矣」——古人有三疾，今恐并此而无之。古之狂尚有节制（肆），今之狂则放荡；古之矜尚有棱角（廉），今之矜则忿戾；古之愚尚直，今之愚则诈而已。叹世风之降。"},{id:"shiqi",label:"十七、巧言令色，鲜矣仁",showLabel:!0,sentences:[["子曰：“巧言令色，鲜矣仁。”"]],note:"「巧言令色，鲜矣仁」——巧言令色者，仁鲜矣。（与《学而》第三章重出。）"},{id:"shiba",label:"十八、恶紫之夺朱也",showLabel:!0,sentences:[["子曰：“恶紫之夺朱也，恶郑声之乱雅乐也，恶利口之覆邦家者。”"]],note:"「恶紫之夺朱也，恶郑声之乱雅乐也，恶利口之覆邦家者」——恶紫色之夺朱红正色，恶郑声之乱雅乐，恶利口之覆邦家。三恶皆以似是而非者乱真。"},{id:"shijiu",label:"十九、天何言哉",showLabel:!0,sentences:[["子曰：“予欲无言。”子贡曰：“子如不言，则小子何述焉？”子曰：“天何言哉？四时行焉，百物生焉，天何言哉？”"]],note:"孔子曰：「予欲无言」。子贡曰：「子如不言，则小子何述焉」——您若不言，小子们何所传述？孔子曰：「天何言哉？四时行焉，百物生焉，天何言哉」——天何言哉？四时行焉，百物生焉。天何言哉！"},{id:"ershi",label:"二十、孺悲欲见孔子",showLabel:!0,sentences:[["孺悲欲见孔子，孔子辞以疾。将命者出户，取瑟而歌，使之闻之。"]],note:"孺悲欲见孔子，孔子辞以疾。将命者出户，孔子取瑟而歌，使之闻之（示非真病，特不欲见耳）。"},{id:"ershiyi",label:"二十一、三年之丧",showLabel:!0,sentences:[["宰我问：“三年之丧，期已久矣！君子三年不为礼，礼必坏；三年不为乐，乐必崩。旧谷既没，新谷既升，",{text:"钻燧改火",glossary:"zuansuigaihuo"},"，期可已矣。”子曰：“食夫稻，衣夫锦，于女安乎？”曰：“安！”“女安则为之！夫君子之居丧，食旨不甘，闻乐不乐，居处不安，故不为也。今女安，则为之！”宰我出，子曰：“予之不仁也！子生三年，然后免于父母之怀。夫三年之丧，天下之通丧也，予也有三年之爱于其父母乎！”"]],note:"宰我问：「三年之丧，期已久矣！君子三年不为礼，礼必坏；三年不为乐，乐必崩。旧谷既没，新谷既升，钻燧改火，期可已矣」——三年之丧太久；君子三年不为礼乐，礼乐必坏；旧谷已尽、新谷已升、取火之木已轮换，一年可止。孔子曰：「食夫稻，衣夫锦，于女（汝）安乎」？曰「安」。「女安则为之」——汝安则为之。又曰：「夫君子之居丧，食旨不甘，闻乐不乐，居处不安，故不为也。今女安，则为之」。宰我出，孔子曰：「予之不仁也！子生三年，然后免于父母之怀。夫三年之丧，天下之通丧也，予也有三年之爱于其父母乎」——宰我不仁啊！子生三年方免于父母之怀；三年之丧，天下之通丧也，宰我岂无三年之爱于其父母乎？"},{id:"ershier",label:"二十二、饱食终日，无所用心",showLabel:!0,sentences:[["子曰：“饱食终日，无所用心，难矣哉！不有",{text:"博弈",glossary:"boyi"},"者乎？为之犹贤乎已。”"]],note:"「饱食终日，无所用心，难矣哉！不有博弈者乎？为之犹贤乎已」——饱食终日、无所用心，难矣哉！不是有博弈之戏吗？为之犹胜于无所事事。"},{id:"ershisan",label:"二十三、君子义以为上",showLabel:!0,sentences:[["子路曰：“君子尚勇乎？”子曰：“君子",{text:"义以为上",glossary:"yiyiweishang"},"。君子有勇而无义为乱，小人有勇而无义为盗。”"]],note:"子路曰：「君子尚勇乎」？孔子曰：「君子义以为上。君子有勇而无义为乱，小人有勇而无义为盗」——君子以义为上；君子有勇无义则为乱，小人有勇无义则为盗。"},{id:"ershisi",label:"二十四、君子亦有恶乎",showLabel:!0,sentences:[["子贡曰：“君子亦有恶乎？”子曰：“有恶。恶称人之恶者，恶居下流而",{text:"讪",glossary:"shan"},"上者，恶勇而无礼者，恶果敢而",{text:"窒",glossary:"zhi"},"者。”曰：“赐也亦有恶乎？”“恶",{text:"徼",glossary:"jiao"},"以为知者，恶不孙以为勇者，恶",{text:"讦",glossary:"jie"},"以为直者。”"]],note:"子贡曰：「君子亦有恶乎」？孔子曰：「有恶：恶称人之恶者，恶居下流而讪上者，恶勇而无礼者，恶果敢而窒者」——有恶：恶称扬人之恶者、恶居下位而毁谤上位者、恶勇而无礼者、恶果敢而不通事理者。曰：「赐也亦有恶乎」？「恶徼以为知者，恶不孙（逊）以为勇者，恶讦以为直者」——恶抄袭以为智、恶不逊以为勇、恶揭人隐私以为直。"},{id:"ershiwu",label:"二十五、唯女子与小人为难养也",showLabel:!0,sentences:[["子曰：“唯女子与小人为难养也，近之则不孙，远之则怨。”"]],note:"「唯女子与小人为难养也，近之则不孙（逊），远之则怨」——唯女子与小人为难处（养＝相处）：近之则不逊，远之则怨。此章历来聚讼纷纭，须顾及当时语境。"},{id:"ershiliu",label:"二十六、年四十而见恶焉",showLabel:!0,sentences:[["子曰：“年四十而见恶焉，其终也已。”"]],note:"「年四十而见恶焉，其终也已」——年四十而为人所恶，其终生也就如此了。"}],r=[{id:"kui",term:"归",pinyin:"kuì",meaning:"同「馈」，赠送。阳货送孔子一只蒸熟的小猪，按礼孔子须回拜。"},{id:"tun",term:"豚",pinyin:"tún",meaning:"小猪。"},{id:"qi-ji",term:"亟",pinyin:"qì",meaning:"屡次。好从事而亟失时：喜欢做官却屡次错过时机。"},{id:"xiange",term:"弦歌",pinyin:"xián gē",meaning:"弹琴瑟唱诗，指礼乐教化。"},{id:"waner",term:"莞尔",pinyin:"wǎn ěr",meaning:"微笑的样子。"},{id:"pan-pan",term:"畔",pinyin:"pàn",meaning:"同「叛」。公山弗扰以费畔：公山弗扰据费邑反叛季氏。"},{id:"wu-wu",term:"侮",pinyin:"wǔ",meaning:"轻慢、欺侮。恭则不侮：恭敬待人就招不来轻慢。"},{id:"lin-lin",term:"磷",pinyin:"lín",meaning:"薄、磨损。磨而不磷：磨也磨不薄。"},{id:"nieerbuzi",term:"涅而不缁",pinyin:"niè ér bù zī",meaning:"涅：黑色染料；缁：黑色。用涅染也染不黑——喻至坚至白者不受污染。"},{id:"paogua",term:"匏瓜",pinyin:"páo guā",meaning:"葫芦（味苦不能食，只能系而悬之）。喻中看不中用、挂而不食。"},{id:"bi-bi2",term:"蔽",pinyin:"bì",meaning:"弊病、蒙蔽。「六言六蔽」：六种德行各有其弊。"},{id:"zei",term:"贼",pinyin:"zéi",meaning:"害。好信不好学，其蔽也贼：只讲信而不好学，弊在被人利用而害己。"},{id:"er",term:"迩",pinyin:"ěr",meaning:"近。迩之事父：近可以用来事奉父母。"},{id:"zhengqiangmianerli",term:"正墙面而立",pinyin:"zhèng qiáng miàn ér lì",meaning:"正对着墙壁站着——什么都看不见、走不通。"},{id:"ren",term:"荏",pinyin:"rěn",meaning:"柔弱、怯懦。色厉而内荏：外表严厉，内心虚弱。"},{id:"chuanyu",term:"穿窬",pinyin:"chuān yú",meaning:"穿：穿壁；窬：同「逾」，跳墙。指打洞翻墙的盗贼。"},{id:"xiangyuan",term:"乡愿",pinyin:"xiāng yuàn",meaning:"乡里那些谁也不得罪、貌似忠厚而没有是非的人（孟子释为「阉然媚于世者」）。"},{id:"bifu",term:"鄙夫",pinyin:"bǐ fū",meaning:"见识浅陋、贪图禄位的人。"},{id:"si",term:"肆",pinyin:"sì",meaning:"放纵（此处的「肆」尚有直率放任之意，与下文「荡」的无所依归有别）。"},{id:"jin-jin",term:"矜",pinyin:"jīn",meaning:"矜持、自负。古之矜也廉：古人自负还有棱角（廉：棱角、有守）；今人则是愤怒乖戾。"},{id:"fenli",term:"忿戾",pinyin:"fèn lì",meaning:"忿怒乖张。"},{id:"zuansuigaihuo",term:"钻燧改火",pinyin:"zuān suì gǎi huǒ",meaning:"上古四季取火所用木材不同，一季一换，一年轮遍。「改火」为一年的标志。"},{id:"boyi",term:"博弈",pinyin:"bó yì",meaning:"博：六博（一种棋）；弈：围棋。泛指游戏。"},{id:"yiyiweishang",term:"义以为上",pinyin:"yì yǐ wéi shàng",meaning:"以义为最高。勇必须由义来指导。"},{id:"shan",term:"讪",pinyin:"shàn",meaning:"诽谤、讥讽。恶居下流而讪上者：厌恶身处下位却诽谤上位者的人。"},{id:"zhi",term:"窒",pinyin:"zhì",meaning:"不通、顽固。果敢而窒：敢作敢为却不通事理。"},{id:"jiao",term:"徼",pinyin:"jiāo",meaning:"抄袭、剽窃（一说为「伺察」）。恶徼以为知者：厌恶把抄来的当自己的智慧的人。"},{id:"jie",term:"讦",pinyin:"jié",meaning:"揭发别人的阴私。恶讦以为直者：厌恶把揭人短处当直率的人。"}];return(d,n)=>{const o=e("DaoTextReading"),l=e("DaoKeywordCards");return m(),h("div",null,[n[0]||(n[0]=i('<h1 id="论语·阳货" tabindex="-1">论语·阳货 <a class="header-anchor" href="#论语·阳货" aria-label="Permalink to &quot;论语·阳货&quot;">​</a></h1><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2><p>《阳货》二十六章，开篇一章很特别——<strong>是《论语》中最像「对手戏」的一段</strong>。阳货（阳虎）当权，想拉孔子出来做官，送了礼又堵着人；孔子挑他不在时回拜，偏又在路上撞见。阳货一路逼问，孔子只答「诺，吾将仕矣」。</p><p>往后各章，有几句分量极重：<strong>「性相近也，习相远也」</strong>——《论语》中论人性最直接的一句；<strong>「割鸡焉用牛刀」</strong>——孔子与子游的机锋，最后以「前言戏之耳」收场；<strong>「六言六蔽」</strong>——六种好品质各有其弊，全都因为「不好学」；<strong>「《诗》可以兴，可以观，可以群，可以怨」</strong>——中国最早的诗论；<strong>「乡愿，德之贼也」「道听而涂说，德之弃也」「色厉而内荏」「患得患失」</strong>；以及**「天何言哉？四时行焉，百物生焉」**。</p><p>第二十一章「三年之丧」是全篇最长的一段：宰我认为三年太久，孔子只问一句「于女安乎」，待弟子走了才说重话——<strong>「予之不仁也」</strong>。</p><p>默认竹简沉浸通读；切「经典阅读」可点生词。</p>',6)),t(o,{colophon:"阳货第十七 · 二十六章",tone:"ink",sections:s,glossary:r,"default-mode":"slips","aria-label":"论语·阳货 原文"}),n[1]||(n[1]=a("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[u("【原典层】注音与字词 "),a("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),t(l,{items:[{term:"归",pinyin:["kuì"],meaning:"同「馈」，赠送。阳货送孔子一只蒸熟的小猪，按礼孔子须回拜。"},{term:"豚",pinyin:["tún"],meaning:"小猪。"},{term:"亟",pinyin:["qì"],meaning:"屡次。好从事而亟失时：喜欢做官却屡次错过时机。"},{term:"弦歌",pinyin:["xián","gē"],meaning:"弹琴瑟唱诗，指礼乐教化。"},{term:"莞尔",pinyin:["wǎn","ěr"],meaning:"微笑的样子。"},{term:"畔",pinyin:["pàn"],meaning:"同「叛」。公山弗扰以费畔：公山弗扰据费邑反叛季氏。"},{term:"侮",pinyin:["wǔ"],meaning:"轻慢、欺侮。恭则不侮：恭敬待人就招不来轻慢。"},{term:"磷",pinyin:["lín"],meaning:"薄、磨损。磨而不磷：磨也磨不薄。"},{term:"涅而不缁",pinyin:["niè","ér","bù","zī"],meaning:"涅：黑色染料；缁：黑色。用涅染也染不黑——喻至坚至白者不受污染。"},{term:"匏瓜",pinyin:["páo","guā"],meaning:"葫芦（味苦不能食，只能系而悬之）。喻中看不中用、挂而不食。"},{term:"蔽",pinyin:["bì"],meaning:"弊病、蒙蔽。「六言六蔽」：六种德行各有其弊。"},{term:"贼",pinyin:["zéi"],meaning:"害。好信不好学，其蔽也贼：只讲信而不好学，弊在被人利用而害己。"},{term:"迩",pinyin:["ěr"],meaning:"近。迩之事父：近可以用来事奉父母。"},{term:"正墙面而立",pinyin:["zhèng","qiáng","miàn","ér","lì"],meaning:"正对着墙壁站着——什么都看不见、走不通。"},{term:"荏",pinyin:["rěn"],meaning:"柔弱、怯懦。色厉而内荏：外表严厉，内心虚弱。"},{term:"穿窬",pinyin:["chuān","yú"],meaning:"穿：穿壁；窬：同「逾」，跳墙。指打洞翻墙的盗贼。"},{term:"乡愿",pinyin:["xiāng","yuàn"],meaning:"乡里那些谁也不得罪、貌似忠厚而没有是非的人（孟子释为「阉然媚于世者」）。"},{term:"鄙夫",pinyin:["bǐ","fū"],meaning:"见识浅陋、贪图禄位的人。"},{term:"肆",pinyin:["sì"],meaning:"放纵（此处的「肆」尚有直率放任之意，与下文「荡」的无所依归有别）。"},{term:"矜",pinyin:["jīn"],meaning:"矜持、自负。古之矜也廉：古人自负还有棱角（廉：棱角、有守）；今人则是愤怒乖戾。"},{term:"忿戾",pinyin:["fèn","lì"],meaning:"忿怒乖张。"},{term:"钻燧改火",pinyin:["zuān","suì","gǎi","huǒ"],meaning:"上古四季取火所用木材不同，一季一换，一年轮遍。「改火」为一年的标志。"},{term:"博弈",pinyin:["bó","yì"],meaning:"博：六博（一种棋）；弈：围棋。泛指游戏。"},{term:"义以为上",pinyin:["yì","yǐ","wéi","shàng"],meaning:"以义为最高。勇必须由义来指导。"},{term:"讪",pinyin:["shàn"],meaning:"诽谤、讥讽。恶居下流而讪上者：厌恶身处下位却诽谤上位者的人。"},{term:"窒",pinyin:["zhì"],meaning:"不通、顽固。果敢而窒：敢作敢为却不通事理。"},{term:"徼",pinyin:["jiāo"],meaning:"抄袭、剽窃（一说为「伺察」）。恶徼以为知者：厌恶把抄来的当自己的智慧的人。"},{term:"讦",pinyin:["jié"],meaning:"揭发别人的阴私。恶讦以为直者：厌恶把揭人短处当直率的人。"}]}),n[2]||(n[2]=i('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>《阳货》二十六章，内容最杂，但可以归成三块。</p><p><strong>一是孔子与人接触的几幕</strong>：阳货送礼逼他做官的那场对话（孔子一路退让，话说得极省）；子游治武城、孔子「割鸡焉用牛刀」的机锋（最后承认「前言戏之耳」）；公山弗扰、佛肸来召，孔子想去的两番犹豫（子路两次拦阻，「磨而不磷，涅而不缁」是回答）；孺悲来见，孔子托病又在门内弹瑟让他听见。<strong>这几幕合起来，写出了孔子与「不值得的人事」打交道的分寸与界限。</strong></p><p><strong>二是对人的判断</strong>：性相近习相远、上知下愚不移、乡愿是德之贼、道听途说是德之弃、色厉内荏如穿窬之盗、患得患失者无所不至、古之三疾与今之三疾的对比。<strong>判语普遍很重，眼光很利。</strong></p><p><strong>三是教与学</strong>：六言六蔽（六种美德都因不好学而成弊）、学《诗》可以兴观群怨、不为《周南》《召南》如正墙面而立、三年之丧的争辩、饱食终日无所用心。<strong>这一块的核心是「学」——不学，连好品质也会走偏。</strong></p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>「性相近也，习相远也」是儒家论人性最关键的一句</strong>：孔子不主张天生分善恶，而把差距归给后天的习染——<strong>这句话为「教育有用」提供了根本的依据。</strong></li><li><strong>「六言六蔽」是对「好人也会办坏事」的完整解释</strong>：仁、智、信、直、勇、刚都是好品质，但<strong>不好学，每一种都会走向自己的反面</strong>。这一章几乎是这一篇的中心。</li><li><strong>「诗可以兴观群怨」是中国最早、也最完整的文学功能论</strong>：感发、观察、合群、抒怨——<strong>四字概括了全部《诗经》的用法。</strong></li><li><strong>「乡愿，德之贼也」是道德批评里最锋利的一句</strong>：它针对的不是坏人，而是<strong>那些貌似忠厚、实际没有是非的人</strong>。这一判断后来被孟子大加发挥。</li><li><strong>「天何言哉」给出了一种无声的教化观</strong>：四季运行、百物生长，天不发一言——<strong>真正的力量不必靠言说。</strong></li><li><strong>「三年之丧」一章见两种人</strong>：宰我从功利和制度角度算账（三年不做礼乐，礼崩乐坏），孔子只问一句「安不安」。<strong>一边是效率，一边是情感；孔子选的是情感，但他不强迫，只说「女安则为之」。</strong></li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>遇到不想打交道的人，学孔子那样说话</strong>：不撕破脸，不说好听的话，<strong>只说该说的，然后把界限守住</strong>。</li><li><strong>用好「六言六蔽」检查自己</strong>：我的「直」有没有变成尖刻？我的「信」有没有被人利用？我的「刚」有没有变成固执？<strong>每一种自认为的优点，都该配一句「我在这上面最容易走偏成什么」。</strong></li><li><strong>用「乡愿」警惕自己</strong>：为了不得罪所有人而放弃是非，是更隐蔽的失守。</li><li><strong>用「患得患失」检查贪执</strong>：一件事我之所以放不下，是「想要」还是「怕丢」？<strong>怕丢比想要更容易让人丧失原则。</strong></li><li><strong>学「天何言哉」那种做法</strong>：不必事事表态、处处言说。<strong>把事做成，比说清楚更算数。</strong></li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>《阳货》开篇是一场对峙。阳虎是当时鲁国的权臣，想让孔子来见自己。孔子不去，他就送了一只猪——按礼，孔子必须回拜。孔子特意挑他不在家的时候去，结果在路上撞见了。</p><p>阳虎连问三句：有本事却看着国家乱，算仁吗？想做官却总错过机会，算智吗？日子一天天过去，时间不等人啊。孔子只答了三个字：「诺，吾将仕矣。」</p><p>这不是妥协，是把话说得刚够。</p><p>这一篇里还有两句我很喜欢。「六言六蔽」——六种美德如果不好学，每一种都会变成毛病。仁会变成愚蠢，信会被人利用，直会变成尖刻，勇会变成闯祸。<strong>所以孔子从不夸人「人品好」就完了，他还要问：你学了吗？</strong></p><p>另一句是「天何言哉？四时行焉，百物生焉」。学生问他：您要是不说话，我们传述什么？孔子反问：天说什么了呢？四季照常轮转，万物照常生长。</p><p>还有「三年之丧」那一场。宰我算了笔账，说三年太耽误事，一年就够了。孔子没反驳道理，只问：吃着白米饭、穿着锦缎衣，你心安吗？宰我说心安。孔子说，心安就去做吧。</p><p>后来弟子走了，他才说重话。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「性相近也，习相远也」——我身上哪些是「习」出来的？我在有意选择自己的「习」吗？</li><li>「六言六蔽」——我自认为的优点里，哪一个最容易走偏成弊病？</li><li>「乡愿，德之贼也」——我有没有为了不得罪人而在该表态的时候沉默过？</li><li>「天何言哉」——我是不是话太多、表态太频繁了？把其中一部分换成做事，会怎样？</li><li>「三年之丧」——如果我不同意一条同样重要的规则，我会像宰我那样直说，还是默默照做？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-16">论语·季氏</a>　下篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-18">论语·微子</a></li><li>参考：《论语》朱熹《四书章句集注·论语集注》；杨伯峻《论语译注》</li></ul>',25))])}}});export{c as __pageData,w as default};
